'x_mo-definition'('x_sep--00118',"&quot;A solution selected or prepared to minimize changes in hydrogen ion concentration which would otherwise tend to occur as a result of a chemical reaction. In general, chemical buffers are systems which, once constituted, tend to resist further change due to external influences. Thus it is possible, for example, to make buffers resistant to changes in temperature, pressure, volume, redox potential, or acidity. The commonest buffer in chemical solution systems is the acid-base buffer, which resists changes in pH.&quot; [McGraw-Hill Encyclopedia of Science and Technology:buffer solution &quot;The McGraw-Hill Companies Inc. 2005. Answers.com 15 Nov. 2006. http://www.answers.com/topic/buffers-chemistry.&quot;]") :- x_cid(a65b125bccf4a8).
