'x_mo-definition'('x_sep--00169',"&quot;Secondary antibody probing is an indirect detection protocol. The unbound primary antibody, it is exposed to another antibody, directed at a species-specific portion of the primary antibody. This is known as a secondary antibody, and due to its targeting properties, tends to be referred to as &quot;anti-mouse,&quot; &quot;anti-goat,&quot; etc. The secondary antibody is usually linked to biotin or to a reporter enzyme such as alkaline phosphatase or horseradish peroxidase. This step confers an advantage in that several secondary antibodies will bind one primary antibody, providing enhanced signal.&quot; [Wikipedia:secondary antobody probing &quot;http://en.wikipedia.org/wiki/Western_blot#Two_step&quot;]") :- x_cid(a65b125bccf529).
