'x_mo-definition'('x_sep--00187',"&quot;A fluorescent label is a label that is either a fluorescent molecule, or an enzyme system that generates a fluorescent product, which is linked to a ligand or binder tracer. The tracer is quantified by measuring the amount of light emitted by the tracer at a specific wavelength after exciting the tracer with incident light of a shorter wavelength. Fluorescent molecules include fluorescein and lanthanide chelates such as europium, samarium, and terbium.&quot; [Brendan Glossart:flourescent label &quot;http://www.brendan.com/glossary.html#f&quot;]") :- x_cid(a65b125bccf60e).
