'x_mo-definition'('x_sep--00113',"&quot;Parafilm is a compound substance which is a product of the American Can Company, consisting of a flexible film that is commonly used for sealing or protecting vessels. Because it is stretchy, moldable, waterproof, odorless, thermoplastic, semitransparent and self-adhering, it can be used to make a temporary flexible seal on open vessels (such as flasks or cuvettes) as one might employ plastic wrap. It can also be used to further seal a lidded container against moisture for long term storage.&quot; [Wikipedia:Parafilm &quot;http://en.wikipedia.org/wiki/Parafilm.&quot;]") :- x_cid(a65b125bccf649).
