'x_mo-definition'(x_Organization,"&quot;An organization is a group which the members of an Organization typically have a common \npurpose or function. Note that this class also covers divisions, departments, etc. of organizations.  For example, both the Shell Corporation and the accounting department at Shell would both be instances of Organization.  \nNote too that the existence of an Organization is dependent on the existence \nof at least one member (since Organization is a subclass of Collection).  \nAccordingly, in cases of purely legal organizations, a fictitious member \nshould be assumed.&quot; [SUMO:organisation &quot;The PSI working group for gel based experiments&quot;]") :- x_cid(a65b125bccf65e).
xc_microtheory(a65b125bccf65e,'x_sep-merged-SUMOMt').
xc_source_file(a65b125bccf65e,'c:/snet/petta/repos/openworld_dr/KBs/SUMO-OBO/sep-merged-SUMO.kif').
