xc_mapping_rows(a65b125bccf65e,['organization-organization']).
'x_mo-definition'('x_sep--00062',"&quot;Image analysis software is software which is the extraction of meaningful information from images; mainly from digital images by means of digital image processing techniques. Image analysis tasks can be as simple as reading bar coded tags or as sophisticated as identifying a person from their face.&quot; [PSI:GEL &quot;The PSI Working group for gel based experiments&quot;]") :- x_cid(a65b125bccf65f).
xc_microtheory(a65b125bccf65f,'x_sep-merged-SUMOMt').
