'x_mo-definition'('x_sep--00165',"&quot;Colorimetric detection is an indirect detection protocol that detects proteins  with a substrate that reacts with the reporter enzyme (such as peroxidase) that is bound to the secondary antibody. This converts the soluble dye into an insoluble form of a different colour that precipitates next to the enzyme and thereby stains the nitrocellulose membrane. Development of the blot is then stopped by washing away the soluble dye. Protein levels are evaluated through densitometry (how intense the stain is) or spectrophotometry.&quot; [WIkipedia:colormetric detection &quot;http://en.wikipedia.org/wiki/Western_blot#Colorimetric_detection&quot;]") :- x_cid(a65b125bccf6e9).
